create or replace function public.complete_learner_onboarding(p_idempotency_key text,p_full_name text,p_institute_name text,p_education_level text,p_trade text,p_semester smallint,p_target_role_slug text,p_home_location text,p_mobility text,p_language text,p_profile_consent boolean,p_ai_consent boolean) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare v_user uuid:=auth.uid();begin if v_user is null then raise exception 'unauthenticated';end if;if char_length(p_idempotency_key)<16 then raise exception 'invalid idempotency key';end if;insert into public.idempotency_records(user_id,operation,idempotency_key,status,expires_at) values(v_user,'complete_onboarding',p_idempotency_key,'processing',now()+interval '24 hours') on conflict do nothing;if not found then return;end if;insert into public.learner_profiles(user_id,full_name,institute_name,education_level,trade,current_semester,target_role_slug,home_location,mobility_preference,preferred_language,onboarding_completed_at) values(v_user,p_full_name,p_institute_name,p_education_level,p_trade,p_semester,p_target_role_slug,p_home_location,p_mobility,p_language,now()) on conflict(user_id) do update set full_name=excluded.full_name,institute_name=excluded.institute_name,education_level=excluded.education_level,trade=excluded.trade,current_semester=excluded.current_semester,target_role_slug=excluded.target_role_slug,home_location=excluded.home_location,mobility_preference=excluded.mobility_preference,preferred_language=excluded.preferred_language,onboarding_completed_at=now();insert into public.consent_records(user_id,purpose,granted) values(v_user,'profile_personalization',p_profile_consent),(v_user,'ai_personalization',p_ai_consent);insert into public.transactional_outbox(aggregate_type,aggregate_id,event_type,payload) values('learner',v_user::text,'onboarding.completed',jsonb_build_object('target_role_slug',p_target_role_slug));update public.idempotency_records set status='completed',response_snapshot='{"ok":true}' where user_id=v_user and operation='complete_onboarding' and idempotency_key=p_idempotency_key;end$$;
create or replace function public.complete_diagnostic_attempt(p_idempotency_key text,p_assessment_slug text,p_assessment_version text,p_score smallint,p_responses jsonb) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_user uuid:=auth.uid();v_attempt uuid;v_item jsonb;begin if v_user is null then raise exception 'unauthenticated';end if;if jsonb_typeof(p_responses)<>'array' or jsonb_array_length(p_responses)=0 then raise exception 'responses required';end if;insert into public.idempotency_records(user_id,operation,idempotency_key,status,expires_at) values(v_user,'complete_diagnostic',p_idempotency_key,'processing',now()+interval '24 hours') on conflict do nothing;if not found then select (response_snapshot->>'attempt_id')::uuid into v_attempt from public.idempotency_records where user_id=v_user and operation='complete_diagnostic' and idempotency_key=p_idempotency_key;return v_attempt;end if;insert into public.assessment_attempts(user_id,assessment_slug,assessment_version,status,score,completed_at) values(v_user,p_assessment_slug,p_assessment_version,'completed',p_score,now()) returning id into v_attempt;for v_item in select * from jsonb_array_elements(p_responses) loop insert into public.assessment_responses(attempt_id,question_id,selected_option,confidence,is_correct) values(v_attempt,v_item->>'questionId',(v_item->>'selectedOption')::smallint,(v_item->>'confidence')::smallint,(v_item->>'isCorrect')::boolean);end loop;insert into public.transactional_outbox(aggregate_type,aggregate_id,event_type,payload) values('assessment_attempt',v_attempt::text,'diagnostic.completed',jsonb_build_object('user_id',v_user,'score',p_score));update public.idempotency_records set status='completed',response_snapshot=jsonb_build_object('ok',true,'attempt_id',v_attempt) where user_id=v_user and operation='complete_diagnostic' and idempotency_key=p_idempotency_key;return v_attempt;end$$;
create or replace function public.submit_job_application(p_idempotency_key text,p_job_id text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare v_user uuid:=auth.uid();v_application uuid;begin if v_user is null then raise exception 'unauthenticated';end if;if not exists(select 1 from public.jobs j join public.organizations o on o.id=j.organization_id where j.id=p_job_id and j.status='published' and o.verification_status='verified') then raise exception 'job unavailable';end if;insert into public.idempotency_records(user_id,operation,idempotency_key,status,expires_at) values(v_user,'submit_application',p_idempotency_key,'processing',now()+interval '24 hours') on conflict do nothing;if not found then select (response_snapshot->>'application_id')::uuid into v_application from public.idempotency_records where user_id=v_user and operation='submit_application' and idempotency_key=p_idempotency_key;return v_application;end if;insert into public.consent_records(user_id,purpose,granted) values(v_user,'employer_visibility',true);insert into public.applications(user_id,job_id,status,profile_share_consent,shared_snapshot) values(v_user,p_job_id,'submitted',true,jsonb_build_object('captured_at',now())) returning id into v_application;insert into public.application_events(application_id,event_type,actor_user_id) values(v_application,'submitted',v_user);insert into public.transactional_outbox(aggregate_type,aggregate_id,event_type,payload) values('application',v_application::text,'application.submitted',jsonb_build_object('job_id',p_job_id,'user_id',v_user));update public.idempotency_records set status='completed',response_snapshot=jsonb_build_object('ok',true,'application_id',v_application) where user_id=v_user and operation='submit_application' and idempotency_key=p_idempotency_key;return v_application;end$$;
revoke all on function public.complete_learner_onboarding(text,text,text,text,text,smallint,text,text,text,text,boolean,boolean) from public;grant execute on function public.complete_learner_onboarding(text,text,text,text,text,smallint,text,text,text,text,boolean,boolean) to authenticated;
revoke all on function public.complete_diagnostic_attempt(text,text,text,smallint,jsonb) from public;grant execute on function public.complete_diagnostic_attempt(text,text,text,smallint,jsonb) to authenticated;
revoke all on function public.submit_job_application(text,text) from public;grant execute on function public.submit_job_application(text,text) to authenticated;
